def normalize_phone(s: str) -> str:
    s = ''.join(c for c in s if c.isdigit())
    if len(s) == 10:
        return f'({s[:3]}) {s[3:6]}-{s[6:]}'
    return s

def flatten(xs: list) -> list:
    result = []
    for x in xs:
        if isinstance(x, list):
            result.extend(flatten(x))
        else:
            result.append(x)
    return result

def valid_parens(s: str) -> bool:
    stack = []
    mapping = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    for char in s:
        if char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            stack.append(char)
    return not stack

def fizzbuzz(n: int) -> list:
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

